        remainder_map[rem] = remainder_map.get(rem, 0) + 1
    return count

def difference_array(n, operations):
    diff = [0] * (n + 1)
    for start, end, val in operations:
        diff[start] += val
        if end + 1 <= n:
            diff[end + 1] -= val
    result = []
    current = 0
    for i in range(n):
        current += diff[i]
        result.append(current)
    return result

