def topo_sort(graph):
    in_degree = {n: 0 for n in graph}
    for n in graph:
        for nb in graph[n]:
            in_degree[nb] = in_degree.get(nb, 0) + 1
    q = deque([n for n in in_degree if in_degree[n] == 0])
    result = []
    while q:
        node = q.popleft()
        result.append(node)
        for nb in graph.get(node, []):
            in_degree[nb] -= 1
            if in_degree[nb] == 0:
                q.append(nb)
    return result

